-- ResearchNet database
-- Run with:  psql -U postgres -d researchnet -f sql/database.sql
-- WARNING: this recreates the papers table (old data in it is deleted).

DROP TABLE IF EXISTS paper_keywords, keywords, paper_authors, authors, papers CASCADE;

CREATE TABLE papers (
    id               SERIAL PRIMARY KEY,
    title            VARCHAR(300) NOT NULL,
    authors          VARCHAR(500),
    keywords         VARCHAR(1000),
    abstract_text    TEXT,
    publication_year INT,
    impact_factor    FLOAT,
    quartile         VARCHAR(2) CHECK (quartile IN ('Q1', 'Q2', 'Q3', 'Q4')),
    journal          VARCHAR(300),
    url              VARCHAR(300)
);

-- Two kinds of data:
--  1. 64 REAL papers: titles, authors, years and arXiv links are real. abstract_text is a short
--     one-line summary (not the official abstract). They are arXiv preprints, so they have
--     no impact factor and no quartile (NULL) - impact factors belong to journals.
--  2. 36 SAMPLE papers (title starts with [SAMPLE]): invented papers in invented journals with
--     demo impact factors and quartiles, so the filters and sorting can be tested.
